sql.if:
WITH matching_samples AS MATERIALIZED (
    SELECT s.* FROM dev_sample s
    WHERE s.tenant_key=#{tenant} AND s.company_id=#{companyId} AND s.deleted_token=0
        AND s.id IN (
            SELECT b.id FROM dev_sample b
            WHERE b.tenant_key=#{tenant} AND b.company_id=#{companyId} AND b.deleted_token=0
                AND b.code IN #{code}
            UNION
            SELECT d.sample_id FROM dev_sample_order d
            WHERE d.tenant_key=#{tenant} AND d.company_id=#{companyId}
                AND d.no IN #{code}
        )
)

mapper.sql:
s.tenant_key=#{tenant} AND s.company_id=#{companyId} AND s.deleted_token=0

    AND EXISTS (
        SELECT 1 FROM biz_tag_object tag_object
        WHERE tag_object.tenant_key=#{q.tagFilter.tenant} AND tag_object.object_type='SAMPLE'
          AND tag_object.object_id=s.id
          AND (SELECT COUNT(*) FROM biz_tag_link tag_link
               WHERE tag_link.tenant_key=tag_object.tenant_key AND tag_link.object_ref_id=tag_object.id
                 AND tag_link.tag_id IN #{tagId}
              )=#{q.tagFilter.size}
    )


AND false

        AND (s.code ILIKE #{keyword} OR s.name ILIKE #{keyword}
            OR EXISTS(SELECT 1 FROM dev_sample_order k WHERE k.tenant_key=s.tenant_key AND k.company_id=s.company_id
                AND k.sample_id=s.id AND k.no ILIKE #{keyword}))



        AND s.category_id IN #{id}
    AND false

AND s.year=#{q.year}
AND s.season=#{q.season}
AND s.brand=#{q.brand}
AND s.designer_id=#{q.designerId}
AND o.factory_id=#{q.factoryId}
AND o.maker_id=#{q.makerId}
AND cn.node_code=#{q.nodeCode}
AND EXISTS(SELECT 1 FROM dev_sample_node ln
    WHERE ln.tenant_key=s.tenant_key AND ln.company_id=s.company_id AND ln.sample_order_id=o.id
    AND ln.done_date IS NULL AND ln.plan_date < #{today}) AND o.status IN ('MAKING','WAIT_REVIEW')
AND o.need_date >= #{q.needFrom}
AND o.need_date < (CAST(#{q.needTo} AS date)+1)
AND s.create_time >= (CAST(#{q.createdFrom} AS date)::timestamp AT TIME ZONE 'Asia/Shanghai')
AND s.create_time < ((CAST(#{q.createdTo} AS date)+1)::timestamp AT TIME ZONE 'Asia/Shanghai')

s.tenant_key=#{tenant} AND s.company_id=#{companyId} AND s.deleted_token=0 AND s.status='DEVELOPING'
AND o.status='WAIT_REVIEW' AND s.designer_id=#{ownerId}
AND o.status='MAKING' AND EXISTS(SELECT 1 FROM dev_sample_node n WHERE n.tenant_key=s.tenant_key AND n.company_id=s.company_id AND n.sample_order_id=o.id AND n.done_date IS NULL AND n.plan_date < #{today}) AND cn.owner_id=#{ownerId}
AND false

mapper.update:
UPDATE dev_sample SET version=version+1,update_by=#{actor},update_time=clock_timestamp()
WHERE tenant_key=#{tenant} AND company_id=#{companyId} AND id=#{id} AND deleted_token=0
    AND version=#{expectedVersion} AND version < 2147483647 AND status=#{expectedStatus}
